fn find(a: Vec<i32>, key: i32) -> usize {
    let mut idx: usize = 0;
    let n = a.len();

    while idx < n {
        if a[idx] == key {
            return idx;
        }
        idx += 1;
    }

    // If we reach here, the key was not found
    n
}

